from core.base_model import PhysicsModel import numpy as np from vpython import sphere, vector, color, canvas, rate, box
class ProjectileMotion(PhysicsModel): """平抛运动模型"""
def __init__(self): super().__init__() self.name = "projectile_motion" self.display_name = "平抛运动" self.description = "模拟物体在重力作用下的平抛运动轨迹" self.category = "力学"
# 定义模型参数 self.parameters = { "initial_height": { "type": "float", "default": 10.0, "min": 0.0, "max": 1000.0, "unit": "m", "description": "初始高度" }, "initial_velocity": { "type": "float", "default": 15.0, "min": 0.0, "max": 1000.0, "unit": "m/s", "description": "初始水平速度" }, "gravity": { "type": "float", "default": 9.8, "min": 0.0, "max": 100.0, "unit": "m/s²", "description": "重力加速度" }, "time_step": { "type": "float", "default": 0.1, "min": 0.01, "max": 1.0, "unit": "s", "description": "时间步长" }, "total_time": { "type": "float", "default": 5.0, "min": 0.1, "max": 100.0, "unit": "s", "description": "总模拟时间" } }
def calculate(self, params=None): """计算平抛运动轨迹""" # 使用传入的参数或默认参数 p = self.get_parameters(params)
# 提取参数 h0 = p["initial_height"] v0 = p["initial_velocity"] g = p["gravity"] dt = p["time_step"] total_time = p["total_time"]
# 计算落地时间（如果在total_time内落地） landing_time = np.sqrt(2 * h0 / g) sim_time = min(landing_time, total_time)
# 生成时间点 time_points = np.arange(0, sim_time + dt, dt)
# 计算每个时间点的位置 x_positions = v0 * time_points y_positions = h0 - 0.5 * g * time_points**2
# 组织结果 trajectory = [] for t, x, y in zip(time_points, x_positions, y_positions): if y >= 0: # 只保留地面以上的点 trajectory.append({ "time": t, "position": {"x": float(x), "y": float(y), "z": 0.0} })
return { "trajectory": trajectory, "parameters": p, "metadata": { "landing_time": float(landing_time) if landing_time <= total_time else None, "landing_distance": float(v0 * landing_time) if landing_time <= total_time else None, "max_height": float(h0), "is_complete": landing_time <= total_time } }
def visualize(self, calculation_result, visualization_type="3d_trajectory"): """可视化计算结果""" if visualization_type == "3d_trajectory": # 创建3D可视化场景 scene = canvas(title="平抛运动模拟", width=800, height=600, center=vector(0, 0, 0))
# 创建物体 ball = sphere(pos=vector(0, calculation_result["parameters"]["initial_height"], 0), radius=0.5, color=color.red)
# 创建地面 ground = box(pos=vector(0, -0.1, 0), size=vector(100, 0.2, 10), color=color.green)
# 动画展示轨迹 trajectory = calculation_result["trajectory"] for point in trajectory: rate(30) # 控制动画速度 pos = point["position"] ball.pos = vector(pos["x"], pos["y"], pos["z"])
return {"status": "success", "message": "Visualization completed"}
elif visualization_type == "data_plot": # 返回可绘制图表的数据 trajectory = calculation_result["trajectory"] times = [point["time"] for point in trajectory] x_positions = [point["position"]["x"] for point in trajectory] y_positions = [point["position"]["y"] for point in trajectory]
return { "plot_data": { "x_vs_time": {"x": times, "y": x_positions, "label": "水平位置随时间变化"}, "y_vs_time": {"x": times, "y": y_positions, "label": "垂直位置随时间变化"}, "trajectory": {"x": x_positions, "y": y_positions, "label": "运动轨迹"} } }
else: return {"status": "error", "message": f"Unsupported visualization type: {visualization_type}"}

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import Dict, Any, List, Optional

from core.model_manager import ModelManager

app = FastAPI(title="高中物理可视化API")
model_manager = ModelManager()

# 初始化时发现所有模型
model_manager.discover_models()

class SimulationRequest(BaseModel):
    model_id: str
    parameters: Dict[str, Any]
    visualization_type: str = "3d_trajectory"

class BatchSimulationRequest(BaseModel):
    model_id: str
    parameter_sets: List[Dict[str, Any]]
    fixed_parameters: Dict[str, Any]
    visualization_type: str = "comparison"

@app.get("/api/models")
def get_models():
    """获取所有可用物理模型"""
    return model_manager.get_all_models_info()

@app.get("/api/models/{model_id}")
def get_model(model_id: str):
    """获取特定模型详情"""
    try:
        return model_manager.get_model_info(model_id)
    except KeyError:
        raise HTTPException(status_code=404, detail=f"Model '{model_id}' not found")

@app.post("/api/simulate")
def simulate(request: SimulationRequest):
    """执行模型计算"""
    try:
        model = model_manager.get_model_instance(request.model_id)
        result = model.calculate(request.parameters)
        visualization = model.visualize(result, request.visualization_type)
        return {"calculation_result": result, "visualization": visualization}
    except KeyError:
        raise HTTPException(status_code=404, detail=f"Model '{request.model_id}' not found")
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@app.get("/api/models/{model_id}/presets")
def get_presets(model_id: str):
    """获取模型预设场景"""
    # 这里可以实现预设场景的逻辑
    # 暂时返回一些示例预设
    presets = [
        {"name": "标准场景", "parameters": {"initial_height": 10, "initial_velocity": 15}},
        {"name": "高抛远场景", "parameters": {"initial_height": 20, "initial_velocity": 30}},
        {"name": "低速场景", "parameters": {"initial_height": 5, "initial_velocity": 5}}
    ]
    return presets

@app.post("/api/batch_simulate")
def batch_simulate(request: BatchSimulationRequest):
    """批量执行模拟（比较不同参数）"""
    try:
        model = model_manager.get_model_instance(request.model_id)
        results = []

        for param_set in request.parameter_sets:
            # 合并固定参数和变化参数
            params = {**request.fixed_parameters, **param_set}
            result = model.calculate(params)
            results.append(result)

        # 这里可以实现比较可视化的逻辑
        # 暂时返回所有结果
        return {"results": results}
    except KeyError:
        raise HTTPException(status_code=404, detail=f"Model '{request.model_id}' not found")
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

import numpy as np
from typing import Dict, Any

class ComputationEngine:
    """物理计算引擎"""

    @staticmethod
    def validate_params(params: Dict[str, Any], param_defs: Dict[str, Any]) -> Dict[str, Any]:
        """参数验证与修正"""
        validated = {}
        for name, def_val in param_defs.items():
            value = params.get(name, def_val["default"])
            if "min" in def_val and value < def_val["min"]:
                value = def_val["min"]
            if "max" in def_val and value > def_val["max"]:
                value = def_val["max"]
            validated[name] = value
        return validated

    @staticmethod
    def generate_time_series(total_time: float, time_step: float) -> np.ndarray:
        """生成时间序列"""
        return np.arange(0, total_time + time_step, time_step)

from typing import Dict, Any
import numpy as np

class VisualizationInterface:
    """可视化接口基类"""

    @staticmethod
    def prepare_trajectory_data(trajectory: list) -> Dict[str, Any]:
        """标准化轨迹数据格式"""
        times = [p["time"] for p in trajectory]
        x = [p["position"]["x"] for p in trajectory]
        y = [p["position"]["y"] for p in trajectory]
        return {"times": times, "x": x, "y": y, "z": [0]*len(times)}

    @staticmethod
    def generate_plot_data(calc_result: Dict[str, Any]) -> Dict[str, Any]:
        """生成图表数据"""
        traj = calc_result.get("trajectory", [])
        data = VisualizationInterface.prepare_trajectory_data(traj)
        return {
            "x_vs_time": {"x": data["times"], "y": data["x"], "label": "X位置"},
            "y_vs_time": {"x": data["times"], "y": data["y"], "label": "Y位置"}
        }

from core.base_model import PhysicsModel
import numpy as np
from vpython import sphere, vector, color, canvas, rate, box

class ProjectileMotion(PhysicsModel):
    def __init__(self):
        super().__init__()
        self.name = "projectile_motion"
        self.display_name = "平抛运动"
        self.description = "模拟物体在重力作用下的平抛运动轨迹"
        self.category = "力学"

        self.parameters = {
            "initial_height": {"type": "float", "default": 10.0, "min": 0.0, "max": 1000.0, "unit": "m", "description": "初始高度"},
            "initial_velocity": {"type": "float", "default": 15.0, "min": 0.0, "max": 1000.0, "unit": "m/s", "description": "初始水平速度"},
            "gravity": {"type": "float", "default": 9.8, "min": 0.0, "max": 100.0, "unit": "m/s²", "description": "重力加速度"},
            "time_step": {"type": "float", "default": 0.1, "min": 0.01, "max": 1.0, "unit": "s", "description": "时间步长"},
            "total_time": {"type": "float", "default": 5.0, "min": 0.1, "max": 100.0, "unit": "s", "description": "总模拟时间"}
        }

    def calculate(self, params=None):
        p = self.get_parameters(params)
        h0, v0, g, dt, total_time = (
            p["initial_height"], p["initial_velocity"], 
            p["gravity"], p["time_step"], p["total_time"]
        )

        landing_time = np.sqrt(2 * h0 / g) if g > 0 else total_time
        sim_time = min(landing_time, total_time)
        time_points = np.arange(0, sim_time + dt, dt)

        x_positions = v0 * time_points
        y_positions = h0 - 0.5 * g * time_points**2

        trajectory = []
        for t, x, y in zip(time_points, x_positions, y_positions):
            if y >= 0:
                trajectory.append({
                    "time": float(t),
                    "position": {"x": float(x), "y": float(y), "z": 0.0}
                })

        return {
            "trajectory": trajectory,
            "parameters": p,
            "metadata": {
                "landing_time": float(landing_time) if landing_time <= total_time else None,
                "landing_distance": float(v0 * landing_time) if landing_time <= total_time else None,
                "max_height": float(h0),
                "is_complete": landing_time <= total_time
            }
        }

    def visualize(self, calculation_result, visualization_type="3d_trajectory"):
        if visualization_type == "3d_trajectory":
            result = calculation_result
            scene = canvas(title="平抛运动模拟", width=800, height=600)
            ball = sphere(
                pos=vector(0, result["parameters"]["initial_height"], 0),
                radius=0.5, color=color.red
            )
            ground = box(
                pos=vector(0, -0.1, 0),
                size=vector(100, 0.2, 10),
                color=color.green
            )

            for point in result["trajectory"]:
                rate(30)
                ball.pos = vector(
                    point["position"]["x"], 
                    point["position"]["y"], 
                    point["position"]["z"]
                )
            return {"status": "success"}

        elif visualization_type == "data_plot":
            return {
                "plot_data": {
                    "x_vs_time": {
                        "x": [p["time"] for p in result["trajectory"]],
                        "y": [p["position"]["x"] for p in result["trajectory"]],
                        "label": "水平位置"
                    },
                    "y_vs_time": {
                        "x": [p["time"] for p in result["trajectory"]],
                        "y": [p["position"]["y"] for p in result["trajectory"]],
                        "label": "垂直位置"
                    }
                }
            }
        return {"status": "error", "message": f"不支持的可视化类型: {visualization_type}"}

