from fastapi import FastAPI
from api.routes import router as api_router

app = FastAPI(title="高中物理可视化系统")
app.include_router(api_router, prefix="/api")

@app.get("/")
def read_root():
    return {"message": "高中物理可视化系统已启动"}

def run_cli(self, args: argparse.Namespace) -> None:
    """命令行模式运行"""
    try:
        # 加载模型
        model = self.model_manager.get_model_instance(args.model)

        # 解析参数
        params = {}
        if args.params:
            for param in args.params:
                key, value = param.split("=")
                params[key] = float(value)

        # 执行计算
        result = self.engine.compute(args.model, params)

        # 执行可视化
        visualization = self.visualizer.visualize(model, result, args.visualization)

        # 显示或保存结果
        if args.output:
            self.save_results(result, visualization, args.output)
            print(f"结果已保存到 results/{args.output}_* 文件中")
        else:
            if visualization["type"] in ["2d_plot", "3d_plot"]:
                plt.figure(figsize=(10, 6))
                if visualization["type"] == "2d_plot":
                    plt.plot(visualization["x"], visualization["y"])
                elif visualization["type"] == "3d_plot":
                    ax = plt.axes(projection='3d')
                    ax.plot_surface(
                        np.array(visualization["x"]),
                        np.array(visualization["y"]),
                        np.array(visualization["z"]),
                        cmap='viridis'
                    )
                    ax.set_zlabel(visualization.get("zlabel", ""))

                plt.title(visualization["title"])
                plt.xlabel(visualization["xlabel"])
                plt.ylabel(visualization.get("ylabel", ""))
                if visualization["type"] == "3d_plot":
                    ax.set_zlabel(visualization.get("zlabel", ""))
                plt.grid(True)
                plt.show()
    except Exception as e:
        print(f"错误: {str(e)}")
        if args.model not in [m["name"] for m in self.model_manager.get_all_models_info()]:
            print("\n可用模型:")
            for model in self.model_manager.get_all_models_info():
                print(f"- {model['name']}: {model['display_name']}")
